{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "환자와 처방 내용을 확인하는 투약 전 절차를 실제로 준수하고, 의심스러운 처방은 투약을 보류한 뒤 담당자에게 확인하여 수행 여부를 결정했는지 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동에서 수술 후 환자의 진통제 처방 용량이 평소의 두 배로 입력된 상황을 설명한다.",
          "task": "환자와 처방 내용을 확인하고, 의심되는 용량이 확인되기 전까지 투약하지 않아야 했던 본인의 책임을 설명한다.",
          "action": "환자 확인과 약물·용량·경로·시간 확인 절차 안에서 용량 이상을 발견하고, 투약을 멈춰 담당의에게 확인한 실제 순서를 설명한다.",
          "result": "담당의 확인으로 입력 오류가 밝혀진 결과와 확인된 처방에 따라 투약 수행 여부를 결정한 내용을 설명한다."
        },
        "expectedEvidence": [
          "투약 대상 환자를 확인한 구체적인 방법",
          "처방과 대조하여 약물·용량·경로·시간을 확인한 절차",
          "평소와 다른 용량을 확인이 필요한 처방으로 판단한 근거",
          "투약 보류, 담당의 확인, 확인된 처방에 따른 수행 여부 결정의 연결"
        ]
      },
      "question": "푸른결종합병원 정형외과 병동에서 진통제 처방 용량이 평소의 두 배로 들어왔을 때, 투약 전 확인 절차를 적용한 순서는 무엇이었나요?",
      "answerTip": "한 가지 사례를 골라 본인이 했던 일을 차례대로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "환자 확인과 약물·용량·경로·시간 확인을 실제 행동과 순서로 구체적으로 설명한다.",
            "용량을 의심한 근거와 투약을 보류하고 담당의에게 확인한 행동이 명확하다.",
            "입력 오류 확인 결과와 이후 확인된 처방에 따라 수행 여부를 결정한 내용이 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자 및 처방 확인과 용량 이상에 대한 투약 보류·담당의 확인이라는 핵심 행동은 드러난다.",
            "확인 항목의 일부, 실제 적용 순서 또는 확인 후 처리 결과의 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "환자·처방 확인에 관한 구체적인 행동이 없거나 일반적인 원칙만 제시한다.",
            "의심되는 처방을 확인하기 전에 투약하거나, 투약 보류와 담당자 확인 여부가 드러나지 않는다.",
            "사례의 오류 발견 결과만 언급하고 본인이 수행한 확인 절차를 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "수술 후 환자 상태를 정해진 주기로 관찰하고, 확인한 변화를 정확한 간호 기록과 필요한 의사 보고 및 다음 근무자 인수인계로 연결했는지 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동에서 수술 후 환자의 활력징후와 통증 등 상태를 관찰했던 구체적인 사례를 설명한다.",
          "task": "정해진 관찰 주기를 지키고 상태 변화를 기록하며, 이상 징후를 담당 의사와 다음 근무자에게 전달해야 했던 역할을 설명한다.",
          "action": "주기적으로 관찰한 상태를 이전 상태와 비교하여 시간과 관찰 내용을 기록하고, 이상 징후를 제때 보고하며 다음 근무자에게 빠짐없이 인계한 절차를 설명한다.",
          "result": "기록에 남은 상태 변화와 의사 보고 및 인수인계에 전달된 내용이 일치하고, 이후 관찰에 필요한 정보가 이어진 결과를 설명한다."
        },
        "expectedEvidence": [
          "환자 상태에 맞춰 정해진 주기로 활력징후·통증·의식 수준 등 필요한 항목을 관찰한 내용",
          "관찰 시각과 상태 변화를 구체적인 수치 또는 관찰 사실로 남긴 기록",
          "이상 징후를 담당 의사에게 보고한 시점과 전달 내용",
          "다음 근무자에게 상태 변화와 이후 관찰에 필요한 정보를 빠짐없이 인계한 내용"
        ]
      },
      "question": "푸른결종합병원 정형외과 병동에서 수술 후 환자의 활력징후와 통증을 관찰했던 사례에서, 상태 변화를 기록·보고·인수인계로 연결한 절차는 무엇이었나요?",
      "answerTip": "기억나는 사례 하나를 중심으로 당시의 일을 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "정해진 관찰 주기와 실제 관찰 항목, 이전 상태와 비교해 확인한 변화를 구체적으로 설명한다.",
            "관찰 시각과 수치 또는 관찰 사실을 간호 기록에 정확히 남긴 행동이 확인된다.",
            "이상 징후를 제때 담당 의사에게 보고한 내용과 다음 근무자에게 인계한 내용이 연결되며, 이후 관찰에 필요한 정보가 전달된 결과가 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자 상태 관찰과 변화 기록, 의사 보고 및 인수인계로 이어지는 핵심 행동은 확인된다.",
            "관찰 주기, 기록의 구체성, 보고 시점 또는 인수인계 내용과 전달 결과 중 일부가 불명확하다."
          ]
        },
        "poor": {
          "criteria": [
            "상태를 관찰하거나 기록했다는 진술만 있고 주기적인 관찰과 변화 기록의 구체적인 근거가 부족하다.",
            "이상 징후의 담당 의사 보고나 다음 근무자 인수인계가 누락되거나 전달 여부를 설명하지 못한다.",
            "환자 상태 변화의 기록·보고·인수인계가 아닌 다른 업무나 일반적인 원칙을 중심으로 답한다."
          ]
        }
      }
    }
  ]
}
